/* hero background butterfly: WebGL particle field formed from dots */
(()=>{'use strict';
const hero=document.getElementById('top');if(!hero)return;
const canvas=document.createElement('canvas');canvas.id='dust-bf';canvas.setAttribute('aria-hidden','true');hero.prepend(canvas);
const hint=document.createElement('span');hint.id='bfhint';hint.className='bfh gone';hero.appendChild(hint);
const D={"gw":512,"gh":341,"step":3,"srcW":1536,"srcH":1024,"count":81200,"mask":"","col":""};
function b64(s){const b=atob(s),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a;}
function mulberry(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
const rnd=mulberry(0x1F123B);

const GW=D.gw,GH=D.gh,STEP=D.step,N=D.count;
const mask=b64(D.mask),colb=b64(D.col);
const ugx=new Uint16Array(N),ugy=new Uint16Array(N);
const cr=new Uint8Array(N),cg=new Uint8Array(N),cb=new Uint8Array(N);
let minX=GW,maxX=0,minY=GH,maxY=0;
{
  let p=0,c=0;const total=GW*GH;
  for(let i=0;i<total;i++){
    if((mask[i>>3]>>(i&7))&1){
      const gx=i%GW,gy=(i/GW)|0;
      ugx[p]=gx;ugy[p]=gy;
      if(gx<minX)minX=gx;if(gx>maxX)maxX=gx;
      if(gy<minY)minY=gy;if(gy>maxY)maxY=gy;
      const o=c*3;cr[p]=colb[o];cg[p]=colb[o+1];cb[p]=colb[o+2];
      p++;c++;
    }
  }
}
const bx0=minX*STEP,by0=minY*STEP,bw=(maxX-minX+1)*STEP,bh=(maxY-minY+1)*STEP;
const bcx=bx0+bw*0.5,bcy=by0+bh*0.5;

for(let i=N-1;i>0;i--){
  const j=(rnd()*(i+1))|0;let t;
  t=ugx[i];ugx[i]=ugx[j];ugx[j]=t;
  t=ugy[i];ugy[i]=ugy[j];ugy[j]=t;
  t=cr[i];cr[i]=cr[j];cr[j]=t;
  t=cg[i];cg[i]=cg[j];cg[j]=t;
  t=cb[i];cb[i]=cb[j];cb[j]=t;
}

const hx=new Float32Array(N),hy=new Float32Array(N);
const pos=new Float32Array(N*2),vel=new Float32Array(N*2),start=new Float32Array(N*2);
const kk=new Float32Array(N),spd=new Float32Array(N),phA=new Float32Array(N),phB=new Float32Array(N),sj=new Float32Array(N);
for(let i=0;i<N;i++){
  kk[i]=30+rnd()*22;
  spd[i]=0.55+rnd()*0.9;
  phA[i]=(rnd()*2048)|0;
  phB[i]=(rnd()*2048)|0;
  sj[i]=0.78+rnd()*0.5;
}
const LUN=2048,SIN=new Float32Array(LUN);
for(let i=0;i<LUN;i++)SIN[i]=Math.sin(i/LUN*6.283185307179586);

const gl=canvas.getContext('webgl',{alpha:true,antialias:false,depth:false,stencil:false,premultipliedAlpha:false});
if(!gl){canvas.remove();hint.remove();return;}
let contextLost=false;
canvas.addEventListener('webglcontextlost',function(e){e.preventDefault();contextLost=true;});
const VSH='attribute vec2 aPos;attribute vec3 aCol;attribute float aSize;uniform vec2 uRes;uniform float uSc;varying vec3 vCol;void main(){vCol=aCol;vec2 c=(aPos*uSc)/uRes*2.0-1.0;gl_Position=vec4(c.x,-c.y,0.0,1.0);gl_PointSize=max(1.0,aSize*uSc);}';
const FSH='precision mediump float;varying vec3 vCol;uniform float uAl;void main(){vec2 d=gl_PointCoord-vec2(0.5);float r=length(d)*2.0;float a=smoothstep(1.0,0.45,r);gl_FragColor=vec4(vCol,uAl*a);}';
function sh(t,s){const o=gl.createShader(t);gl.shaderSource(o,s);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(o));return o;}
const pr=gl.createProgram();
gl.attachShader(pr,sh(gl.VERTEX_SHADER,VSH));
gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,FSH));
gl.linkProgram(pr);
if(!gl.getProgramParameter(pr,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(pr));
gl.useProgram(pr);
const locPos=gl.getAttribLocation(pr,'aPos'),locCol=gl.getAttribLocation(pr,'aCol'),locSize=gl.getAttribLocation(pr,'aSize');
const uRes=gl.getUniformLocation(pr,'uRes'),uSc=gl.getUniformLocation(pr,'uSc'),uAl=gl.getUniformLocation(pr,'uAl');
const colBuf=gl.createBuffer(),posBuf=gl.createBuffer();

const sAb=new ArrayBuffer(N*8),su8=new Uint8Array(sAb),sf32=new Float32Array(sAb);
for(let i=0;i<N;i++){const o=i*8;su8[o]=cr[i];su8[o+1]=cg[i];su8[o+2]=cb[i];su8[o+3]=255;}
let psizeCSS=2;
function uploadStatic(){
  gl.bindBuffer(gl.ARRAY_BUFFER,colBuf);
  for(let i=0;i<N;i++)sf32[i*2+1]=psizeCSS*sj[i];
  gl.bufferData(gl.ARRAY_BUFFER,sAb,gl.STATIC_DRAW);
}

const RM=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let cw=0,ch=0,dpr=1,rs=1,fs=1,dw=0,dh=0,cx=0,cy=0,ox=0,oy=0,R=120,R2=14400,MAXD=162,MAXD2=26244,posInit=false;
function layout(force){
  const rect=hero.getBoundingClientRect();
  const nw=Math.round(rect.width),nh=Math.round(rect.height);
  if(!nw||!nh)return;
  if(!force&&nw===cw&&nh===ch)return;
  cw=nw;ch=nh;
  dpr=Math.min(window.devicePixelRatio||1,2);
  const wide=cw>900;
  const mW=wide?Math.min(cw*0.5,900):Math.min(cw*0.84,480);
  const mH=ch*(wide?0.86:0.34);
  fs=Math.min(mW/bw,mH/bh);
  dw=bw*fs;dh=bh*fs;
  cx=wide?Math.round(cw*0.80):Math.round(cw*0.5);
  cy=wide?Math.round(ch*0.5):Math.round(ch-dh*0.5-42);
  ox=Math.round(cx-dw*0.5);oy=Math.round(cy-dh*0.5);
  R=Math.min(180,Math.max(70,dw*0.19));R2=R*R;
  MAXD=R*1.35;MAXD2=MAXD*MAXD;
  const spacing=STEP*fs;
  psizeCSS=Math.min(3.4,Math.max(1.5,spacing*1.5));
  for(let i=0;i<N;i++){
    hx[i]=cx+((ugx[i]+0.5)*STEP-bcx)*fs;
    hy[i]=cy+((ugy[i]+0.5)*STEP-bcy)*fs;
    if(RM&&posInit){pos[i*2]=hx[i];pos[i*2+1]=hy[i];}
  }
  canvas.width=Math.max(1,Math.round(cw*dpr*rs));
  canvas.height=Math.max(1,Math.round(ch*dpr*rs));
  canvas.style.width=cw+'px';canvas.style.height=ch+'px';
  gl.viewport(0,0,canvas.width,canvas.height);
  uploadStatic();
  hint.style.left=cx+'px';
  hint.style.top=Math.min(ch-34,oy+dh+10)+'px';
  hint.textContent=wide?'Move through the butterfly · click to burst':'Touch the butterfly · tap to burst';
}
layout(true);
gl.enableVertexAttribArray(locCol);gl.vertexAttribPointer(locCol,3,gl.UNSIGNED_BYTE,true,8,0);
gl.enableVertexAttribArray(locSize);gl.vertexAttribPointer(locSize,1,gl.FLOAT,false,8,4);
gl.bindBuffer(gl.ARRAY_BUFFER,posBuf);gl.bufferData(gl.ARRAY_BUFFER,pos.byteLength,gl.DYNAMIC_DRAW);
gl.enableVertexAttribArray(locPos);gl.vertexAttribPointer(locPos,2,gl.FLOAT,false,8,0);
gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);

const INTRO_DUR=RM?0:1250,STAG=RM?0:430;
let introDone=INTRO_DUR===0;
for(let i=0;i<N;i++){
  const i2=i*2;
  if(introDone){pos[i2]=hx[i];pos[i2+1]=hy[i];}
  else{start[i2]=rnd()*cw;start[i2+1]=rnd()*ch;pos[i2]=start[i2];pos[i2+1]=start[i2+1];}
}
posInit=true;

let mx=-1e5,my=-1e5,pmx=-1e5,pmy=-1e5,vis=true;
let hintShown=false,hintHidden=false;
function showHint(){if(!hintShown){hintShown=true;hint.classList.remove('gone');}}
function hideHint(){if(hintShown&&!hintHidden){hintHidden=true;hint.classList.add('gone');}}
function isBlocked(target){return !!(target&&target.closest&&target.closest('#cbw,dialog,#slTray,#slDrawer,nav'));}
function onPointerMove(e){
  if(!vis||isBlocked(e.target)){mx=-1e5;my=-1e5;return;}
  const r=hero.getBoundingClientRect();
  const x=e.clientX-r.left,y=e.clientY-r.top;
  if(x<-R||x>cw+R||y<-R||y>ch+R){mx=-1e5;my=-1e5;return;}
  if(mx<-1e4){pmx=x;pmy=y;}
  mx=x;my=y;
  if(introDone&&x>=ox-36&&x<=ox+dw+36&&y>=oy-36&&y<=oy+dh+36)hideHint();
}
function onPointerDown(e){
  if(!vis||isBlocked(e.target))return;
  if(e.target&&e.target.closest&&e.target.closest('a,button,input,select'))return;
  const r=hero.getBoundingClientRect();
  const x=e.clientX-r.left,y=e.clientY-r.top;
  if(x<0||x>cw||y<0||y>ch)return;
  if(mx<-1e4){pmx=x;pmy=y;}
  mx=x;my=y;
  if(introDone)hideHint();
  burst(x,y);
}
window.addEventListener('pointermove',onPointerMove,{passive:true});
window.addEventListener('pointerdown',onPointerDown,{passive:true});
document.addEventListener('mouseleave',function(){mx=-1e5;my=-1e5;});
window.addEventListener('blur',function(){mx=-1e5;my=-1e5;});
let rz;const rb=()=>{clearTimeout(rz);rz=setTimeout(()=>layout(false),120);};
window.addEventListener('resize',rb);
if(window.ResizeObserver)new ResizeObserver(rb).observe(hero);
if(window.IntersectionObserver)new IntersectionObserver(e=>{vis=e[0].isIntersecting;}).observe(hero);

function burst(bx,by){
  const BR=R*2.3,BR2=BR*BR;
  for(let i=0;i<na;i++){
    const i2=i*2,dx=pos[i2]-bx,dy=pos[i2+1]-by,d2=dx*dx+dy*dy;
    if(d2<BR2&&d2>1){
      const d=Math.sqrt(d2),s=(1-d/BR)*1900+350;
      vel[i2]+=dx/d*s;vel[i2+1]+=dy/d*s;
    }
  }
}

const TIERS=[[1,1],[0.72,0.82],[0.5,0.66]];
let na=N,tier=0,emaDt=16.7,cool=0,up=0;
function setTier(t){tier=t;na=Math.floor(N*TIERS[t][0]);rs=TIERS[t][1];layout(true);}

const FORCE=2700,SWIRL=0.65,DAMP=5.2,VMAX=2400,VMAX2=VMAX*VMAX,WOBB=RM?0:1.25;
const SWIPE=15,DRAG=110;
let last=performance.now(),t0=0,introT0=-1;
window.__dots={n:N,info:function(){return{fps:Math.round(1000/emaDt),tier:tier,active:na,res:rs};}};

function frame(now){
  requestAnimationFrame(frame);
  if(!vis||contextLost){last=now;return;}
  let dtms=now-last;last=now;
  if(dtms>50)dtms=50;if(dtms<=0)dtms=1;
  const dt=dtms/1000;
  emaDt=emaDt*0.94+dtms*0.06;
  if(cool>0)cool--;
  else if(emaDt>24&&tier<2){setTier(tier+1);cool=110;up=0;}
  else if(emaDt<14.6&&tier>0){if(++up>140){setTier(tier-1);cool=110;up=0;}}
  else up=0;
  if(!t0)t0=now;
  if(introT0<0)introT0=now;
  const it=now-introT0,tSec=(now-t0)/1000;

  if(!introDone){
    let done=true;
    for(let i=0;i<na;i++){
      const i2=i*2;
      const dl=phA[i]*0.00048828*STAG;
      let l=(it-dl)/INTRO_DUR;
      if(l<1)done=false;
      if(l<0)l=0;else if(l>1)l=1;
      const e=1-Math.pow(1-l,3);
      pos[i2]=start[i2]+(hx[i]-start[i2])*e;
      pos[i2+1]=start[i2+1]+(hy[i]-start[i2+1])*e;
      vel[i2]=0;vel[i2+1]=0;
    }
    if(done)introDone=true;
  }else{
    showHint();
    const tb=tSec*300;
    const sx=mx-pmx,sy=my-pmy,L2s=sx*sx+sy*sy,L=Math.sqrt(L2s);
    const sxL=L>0.5?sx/L:0,syL=L>0.5?sy/L:0;
    const g=Math.min(1,Math.max(0,(L*1000/dtms-400)/800));
    const imp=Math.min(L,60)*SWIPE*g;
    for(let i=0;i<na;i++){
      const i2=i*2;
      let x=pos[i2],y=pos[i2+1],vx=vel[i2],vy=vel[i2+1];
      let ux,uy,dn2;
      if(L2s>0.25){
        let t=((x-pmx)*sx+(y-pmy)*sy)/L2s;
        t=t<0?0:(t>1?1:t);
        ux=x-(pmx+sx*t);uy=y-(pmy+sy*t);dn2=ux*ux+uy*uy;
        if(dn2<0.25){ux=-sy;uy=sx;dn2=4;}
      }else{
        ux=x-mx;uy=y-my;dn2=ux*ux+uy*uy;
      }
      if(dn2<R2){
        const dn=Math.sqrt(dn2);
        let w=1-dn/R;w*=w;
        let uxn,uyn;
        if(dn>0.5){uxn=ux/dn;uyn=uy/dn;}
        else if(L>0.5){uxn=-syL;uyn=sxL;}
        else{uxn=1;uyn=0;}
        const f=w*FORCE*dt+w*imp;
        const sw=f*SWIRL;
        vx+=uxn*f-uyn*sw;vy+=uyn*f+uxn*sw;
        if(g>0){const dr=w*DRAG*g;vx+=sxL*dr;vy+=syL*dr;}
      }
      const b=tb*spd[i];
      const wx=SIN[(b+phA[i])&2047]*WOBB;
      const wy=SIN[(b*1.31+phB[i])&2047]*WOBB;
      const k=kk[i]*dt;
      vx+=(hx[i]+wx-x)*k;vy+=(hy[i]+wy-y)*k;
      const dm=1-DAMP*dt;vx*=dm;vy*=dm;
      const s2=vx*vx+vy*vy;
      if(s2>VMAX2){const s=VMAX/Math.sqrt(s2);vx*=s;vy*=s;}
      x+=vx*dt;y+=vy*dt;
      const ax=x-hx[i],ay=y-hy[i],ad2=ax*ax+ay*ay;
      if(ad2>MAXD2){const s=MAXD/Math.sqrt(ad2);x=hx[i]+ax*s;y=hy[i]+ay*s;}
      pos[i2]=x;pos[i2+1]=y;vel[i2]=vx;vel[i2+1]=vy;
    }
  }
  pmx=mx;pmy=my;

  const al=0.9*Math.min(1,it/650);
  gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);
  gl.uniform2f(uRes,canvas.width,canvas.height);
  gl.uniform1f(uSc,dpr*rs);
  gl.uniform1f(uAl,al);
  gl.bindBuffer(gl.ARRAY_BUFFER,posBuf);
  gl.bufferSubData(gl.ARRAY_BUFFER,0,pos.subarray(0,na*2));
  gl.drawArrays(gl.POINTS,0,na);
}
requestAnimationFrame(frame);
})();
